UPDATE lessons SET title='Description Studio: Paint a Place with Words',data=json_patch(data,'{"seed_key":"s2-eng-y3-w08-l2","title":"Description Studio: Paint a Place with Words","stage":"Stage 2","learning_area":"English","year_level":3,"week":8,"lesson_number":2,"duration_minutes":60,"child_mission":"Investigate description studio: paint a place with words with detailed modelling and independent practice.","learning_intention":"We are learning to understand and apply description studio: paint a place with words.","success_criteria":["I can describe the key idea.","I can follow and explain a worked model.","I can practise and check feedback.","I can solve an independent challenge.","I can explain an improvement."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Teaching reminders","cards":[{"front":"Start with a topic sentence naming the subject.","back":"The community garden offers a quiet place to walk."},{"front":"Include precise sensory details rather than vague praise.","back":"Tall grasses rustle beside the stone path; the pond''s surface ripples."},{"front":"Organise descriptions in a sensible spatial order.","back":"First describe the path, then the bench, then the pond beyond."},{"front":"Revise vague nouns and verbs to help the reader visualise.","back":"Replace ''nice stuff'' with ''a narrow path curves beside the pond''."}]}],"printable_resource":{"title":"Description Studio: Paint a Place with Words","instructions":"Learn, practise, apply and check.","passage":"A community garden has a winding stone path, tall grasses, a timber bench and a pond with ripples.","prompts":["What do I know?","How does the example work?","Try the independent challenge.","Explain one check."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Start with a topic sentence naming the subject.","explain":"Start with a topic sentence naming the subject. For example: The community garden offers a quiet place to walk.\n\nOriginal source: A community garden has a winding stone path, tall grasses, a timber bench and a pond with ripples.","example":"**Worked thinking:** The community garden offers a quiet place to walk.\n\n**New attempt:** Write 100–140 words describing an outdoor reading nook with a shade tree, two weatherproof seats, a book cabinet and stepping stones. Use a topic sentence, three sensory details, logical spatial order and a closing sentence. Underline two precise verbs and explain one revision.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"The community garden offers a quiet place to walk.","check":{"question":"Which starts a description?","options":["A garden has a path and pond.","A thief ran away.","Here is a maths fact.","Once a dragon spoke."],"correct_index":0,"explanation":"The community garden offers a quiet place to walk."},"visual_before":[{"episode":{"title":"Description Studio: Paint a Place with Words","transcript":"pip: I wrote ''the garden is nice.'' Can you picture it?\njuno: Give the reader concrete details, such as the path and ripples.\npip: The stone path curves beside tall grass and the pond.\njuno: Pause and add a sound detail. Explain what your reader learns.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I wrote ''the garden is nice.'' Can you picture it?"},{"who":"juno","text":"Give the reader concrete details, such as the path and ripples."},{"who":"pip","text":"The stone path curves beside tall grass and the pond."},{"who":"juno","text":"Pause and add a sound detail. Explain what your reader learns.","pause_after":true}]}]}}]},{"icon":"📘","title":"Include precise sensory details rather than vague praise.","explain":"Include precise sensory details rather than vague praise. For example: Tall grasses rustle beside the stone path; the pond''s surface ripples.\n\nOriginal source: A community garden has a winding stone path, tall grasses, a timber bench and a pond with ripples.","example":"**Worked thinking:** Tall grasses rustle beside the stone path; the pond''s surface ripples.\n\n**New attempt:** Write 100–140 words describing an outdoor reading nook with a shade tree, two weatherproof seats, a book cabinet and stepping stones. Use a topic sentence, three sensory details, logical spatial order and a closing sentence. Underline two precise verbs and explain one revision.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"Tall grasses rustle beside the stone path; the pond''s surface ripples.","check":{"question":"Which detail is concrete?","options":["Wooden bench","Really nice","Some stuff","Quite good"],"correct_index":0,"explanation":"Tall grasses rustle beside the stone path; the pond''s surface ripples."}},{"icon":"✏️","title":"Organise descriptions in a sensible spatial order.","explain":"Organise descriptions in a sensible spatial order. For example: First describe the path, then the bench, then the pond beyond.\n\nOriginal source: A community garden has a winding stone path, tall grasses, a timber bench and a pond with ripples.","example":"**Worked thinking:** First describe the path, then the bench, then the pond beyond.\n\n**New attempt:** Write 100–140 words describing an outdoor reading nook with a shade tree, two weatherproof seats, a book cabinet and stepping stones. Use a topic sentence, three sensory details, logical spatial order and a closing sentence. Underline two precise verbs and explain one revision.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"First describe the path, then the bench, then the pond beyond.","check":{"question":"Which is a precise verb?","options":["Curves","Thing","Nice","Stuff"],"correct_index":0,"explanation":"First describe the path, then the bench, then the pond beyond."}},{"icon":"✅","title":"Revise vague nouns and verbs to help the reader visualise.","explain":"Revise vague nouns and verbs to help the reader visualise. For example: Replace ''nice stuff'' with ''a narrow path curves beside the pond''.\n\nOriginal source: A community garden has a winding stone path, tall grasses, a timber bench and a pond with ripples.","example":"**Worked thinking:** Replace ''nice stuff'' with ''a narrow path curves beside the pond''.\n\n**New attempt:** Write 100–140 words describing an outdoor reading nook with a shade tree, two weatherproof seats, a book cabinet and stepping stones. Use a topic sentence, three sensory details, logical spatial order and a closing sentence. Underline two precise verbs and explain one revision.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"Replace ''nice stuff'' with ''a narrow path curves beside the pond''.","check":{"question":"What helps organise a place?","options":["Spatial order","Random events","Unrelated stories","No topic"],"correct_index":0,"explanation":"Replace ''nice stuff'' with ''a narrow path curves beside the pond''."}}],"worked_example":"1. The community garden offers a quiet place to walk.\n\n2. Tall grasses rustle beside the stone path; the pond''s surface ripples.\n\n3. First describe the path, then the bench, then the pond beyond.\n\n4. Replace ''nice stuff'' with ''a narrow path curves beside the pond''.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 550 150\"><rect width=\"550\" height=\"150\" rx=\"9\" fill=\"#f2f7f3\"/><rect x=\"10\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#dcece3\"/><text x=\"17\" y=\"76\" font-family=\"Arial\" font-size=\"15\">NOTICE</text><rect x=\"146\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#e7ebf7\"/><text x=\"153\" y=\"76\" font-family=\"Arial\" font-size=\"15\">EXPLAIN</text><rect x=\"282\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#dcece3\"/><text x=\"289\" y=\"76\" font-family=\"Arial\" font-size=\"15\">APPLY</text><rect x=\"418\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#e7ebf7\"/><text x=\"425\" y=\"76\" font-family=\"Arial\" font-size=\"15\">VERIFY</text></svg>","alt":"Four phases of Description Studio: Paint a Place with Words","caption":"Notice, explain, apply and verify."}],"guided_practice":"Study these original examples before trying an independent response: A community garden has a winding stone path, tall grasses, a timber bench and a pond with ripples.\n\nThe community garden offers a quiet place to walk. Tall grasses rustle beside the stone path; the pond''s surface ripples. First describe the path, then the bench, then the pond beyond. Replace ''nice stuff'' with ''a narrow path curves beside the pond''.\n\nExplain one choice before comparing it with this model.","independent_task":"Write 100–140 words describing an outdoor reading nook with a shade tree, two weatherproof seats, a book cabinet and stepping stones. Use a topic sentence, three sensory details, logical spatial order and a closing sentence. Underline two precise verbs and explain one revision.","response_prompt":"Write 100–140 words describing an outdoor reading nook with a shade tree, two weatherproof seats, a book cabinet and stepping stones. Use a topic sentence, three sensory details, logical spatial order and a closing sentence. Underline two precise verbs and explain one revision.","quiz":[{"type":"multiple_choice","question":"Which starts a description?","options":["A garden has a path and pond.","A thief ran away.","Here is a maths fact.","Once a dragon spoke."],"correct_index":0,"explanation":"A garden has a path and pond.. Compare with the taught example."},{"type":"multiple_choice","question":"Which detail is concrete?","options":["Wooden bench","Really nice","Some stuff","Quite good"],"correct_index":0,"explanation":"Wooden bench. Compare with the taught example."},{"type":"multiple_choice","question":"Which is a precise verb?","options":["Curves","Thing","Nice","Stuff"],"correct_index":0,"explanation":"Curves. Compare with the taught example."},{"type":"multiple_choice","question":"What helps organise a place?","options":["Spatial order","Random events","Unrelated stories","No topic"],"correct_index":0,"explanation":"Spatial order. Compare with the taught example."},{"type":"multiple_choice","question":"Which is sound imagery?","options":["Grasses rustle","Bench is brown","Stones are grey","Pond is small"],"correct_index":0,"explanation":"Grasses rustle. Compare with the taught example."},{"type":"multiple_choice","question":"Which detail is invented?","options":["Stone path","Pond ripples","A dragon lives by the pond","Wooden bench"],"correct_index":2,"explanation":"A dragon lives by the pond. Compare with the taught example."},{"type":"multiple_choice","question":"Which is a clear sentence?","options":["The path winds toward the pond.","Stuff is nice.","Things are things.","It is good."],"correct_index":0,"explanation":"The path winds toward the pond.. Compare with the taught example."},{"type":"multiple_choice","question":"What should revision improve?","options":["Clarity and precision","Only length","More unrelated words","Pencil colour"],"correct_index":0,"explanation":"Clarity and precision. Compare with the taught example."},{"type":"short_answer","question":"Complete the original independent challenge with supporting evidence or calculations.","sample_answer":"A leafy tree shades a little reading nook. Stepping stones curve towards two weatherproof seats, and a cabinet holds books nearby. The breeze stirs the leaves above as sunlight moves over the path. It is a calm place to settle with a story.","marking_guide":"Check complete, accurate topic-specific content and reasoning.","explanation":"An answer should show its method."},{"type":"short_answer","question":"Explain a relevant correction or improvement.","sample_answer":"I replaced ''nice'' with exact descriptions of the stones, shade and seats. I ordered the description from the entrance to the reading area so the reader can picture it.","marking_guide":"Check complete, accurate topic-specific content and reasoning.","explanation":"An answer should show its method."}],"parent_notes":"Parent: Require the child''s original work before revealing marking models.\n\nParent: First model answer: A leafy tree shades a little reading nook. Stepping stones curve towards two weatherproof seats, and a cabinet holds books nearby. The breeze stirs the leaves above as sunlight moves over the path. It is a calm place to settle with a story.\n\nParent: Second model answer: I replaced ''nice'' with exact descriptions of the stones, shade and seats. I ordered the description from the entrance to the reading area so the reader can picture it.\n\nParent: Keep evidence and verify NESA outcomes before approval.","evidence_instructions":"Keep the independent response, one revision and both written answers.","offline_alternative":"Complete the example and task on paper and keep the result.","extension":"Create another example of description studio: paint a place with words and explain it.","stage_hints":{"accept":["Read the Description Studio: Paint a Place with Words instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach0":["Read the Start with a topic sentence naming the subject. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach1":["Read the Include precise sensory details rather than vague praise. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach2":["Read the Organise descriptions in a sensible spatial order. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach3":["Read the Revise vague nouns and verbs to help the reader visualise. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"learn":["Read the Description Studio: Paint a Place with Words instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"guided":["Read the Description Studio: Paint a Place with Words instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"write":["Read the Description Studio: Paint a Place with Words instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"quiz":["Read the Description Studio: Paint a Place with Words instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"submit":["Read the Description Studio: Paint a Place with Words instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."]}}') WHERE seed_key='s2-eng-y3-w08-l2';
UPDATE lessons SET title='Timeless Present: Write Accurate General Facts',data=json_patch(data,'{"seed_key":"s2-eng-y3-w08-l3","title":"Timeless Present: Write Accurate General Facts","stage":"Stage 2","learning_area":"English","year_level":3,"week":8,"lesson_number":3,"duration_minutes":60,"child_mission":"Investigate timeless present: write accurate general facts with detailed modelling and independent practice.","learning_intention":"We are learning to understand and apply timeless present: write accurate general facts.","success_criteria":["I can describe the key idea.","I can follow and explain a worked model.","I can practise and check feedback.","I can solve an independent challenge.","I can explain an improvement."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Teaching reminders","cards":[{"front":"Use simple present tense for general facts.","back":"A wombat digs burrows; ''dug yesterday'' describes a past event."},{"front":"Match singular and plural subjects to verbs.","back":"A bee visits flowers, but bees visit flowers."},{"front":"Keep tense consistent within a general explanation.","back":"Change ''Wombats dig and used claws'' to ''Wombats dig and use claws''."},{"front":"Separate dated past events from ongoing general facts.","back":"Yesterday a magpie visited the yard; birds have feathers."}]}],"printable_resource":{"title":"Timeless Present: Write Accurate General Facts","instructions":"Learn, practise, apply and check.","passage":"A report states ''A wombat digs burrows. Wombats have strong claws. Their burrows provide shelter.''","prompts":["What do I know?","How does the example work?","Try the independent challenge.","Explain one check."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Use simple present tense for general facts.","explain":"Use simple present tense for general facts. For example: A wombat digs burrows; ''dug yesterday'' describes a past event.\n\nOriginal source: A report states ''A wombat digs burrows. Wombats have strong claws. Their burrows provide shelter.''","example":"**Worked thinking:** A wombat digs burrows; ''dug yesterday'' describes a past event.\n\n**New attempt:** Revise: ''Birds has feathers. A kookaburra eat insects and sometimes calls loudly. Many birds built nests to raise young. Yesterday a magpie visits our yard.'' Use timeless present for general facts, past tense for the dated observation, and explain three verb corrections.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"A wombat digs burrows; ''dug yesterday'' describes a past event.","check":{"question":"General present fact?","options":["A wombat digs burrows.","A wombat dug yesterday.","Tomorrow it will dig.","I saw it last week."],"correct_index":0,"explanation":"A wombat digs burrows; ''dug yesterday'' describes a past event."},"visual_before":[{"episode":{"title":"Timeless Present: Write Accurate General Facts","transcript":"pip: My report says wombats dug burrows. Is that right?\njuno: For a specific past event, yes. General facts use present tense.\npip: Wombats dig burrows; a wombat digs burrows.\njuno: Good. Pause and explain why those two verbs are different.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"My report says wombats dug burrows. Is that right?"},{"who":"juno","text":"For a specific past event, yes. General facts use present tense."},{"who":"pip","text":"Wombats dig burrows; a wombat digs burrows."},{"who":"juno","text":"Good. Pause and explain why those two verbs are different.","pause_after":true}]}]}}]},{"icon":"📘","title":"Match singular and plural subjects to verbs.","explain":"Match singular and plural subjects to verbs. For example: A bee visits flowers, but bees visit flowers.\n\nOriginal source: A report states ''A wombat digs burrows. Wombats have strong claws. Their burrows provide shelter.''","example":"**Worked thinking:** A bee visits flowers, but bees visit flowers.\n\n**New attempt:** Revise: ''Birds has feathers. A kookaburra eat insects and sometimes calls loudly. Many birds built nests to raise young. Yesterday a magpie visits our yard.'' Use timeless present for general facts, past tense for the dated observation, and explain three verb corrections.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"A bee visits flowers, but bees visit flowers.","check":{"question":"Correct singular form?","options":["A bee visits flowers.","A bee visit flowers.","A bee visited always.","A bee are visiting."],"correct_index":0,"explanation":"A bee visits flowers, but bees visit flowers."}},{"icon":"✏️","title":"Keep tense consistent within a general explanation.","explain":"Keep tense consistent within a general explanation. For example: Change ''Wombats dig and used claws'' to ''Wombats dig and use claws''.\n\nOriginal source: A report states ''A wombat digs burrows. Wombats have strong claws. Their burrows provide shelter.''","example":"**Worked thinking:** Change ''Wombats dig and used claws'' to ''Wombats dig and use claws''.\n\n**New attempt:** Revise: ''Birds has feathers. A kookaburra eat insects and sometimes calls loudly. Many birds built nests to raise young. Yesterday a magpie visits our yard.'' Use timeless present for general facts, past tense for the dated observation, and explain three verb corrections.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"Change ''Wombats dig and used claws'' to ''Wombats dig and use claws''.","check":{"question":"Correct plural form?","options":["Bees visits flowers.","Bees visit flowers.","Bees has visits.","Bees is visit."],"correct_index":1,"explanation":"Change ''Wombats dig and used claws'' to ''Wombats dig and use claws''."}},{"icon":"✅","title":"Separate dated past events from ongoing general facts.","explain":"Separate dated past events from ongoing general facts. For example: Yesterday a magpie visited the yard; birds have feathers.\n\nOriginal source: A report states ''A wombat digs burrows. Wombats have strong claws. Their burrows provide shelter.''","example":"**Worked thinking:** Yesterday a magpie visited the yard; birds have feathers.\n\n**New attempt:** Revise: ''Birds has feathers. A kookaburra eat insects and sometimes calls loudly. Many birds built nests to raise young. Yesterday a magpie visits our yard.'' Use timeless present for general facts, past tense for the dated observation, and explain three verb corrections.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"Yesterday a magpie visited the yard; birds have feathers.","check":{"question":"Tense for yesterday?","options":["Past","Future","Timeless present only","No verb"],"correct_index":0,"explanation":"Yesterday a magpie visited the yard; birds have feathers."}}],"worked_example":"1. A wombat digs burrows; ''dug yesterday'' describes a past event.\n\n2. A bee visits flowers, but bees visit flowers.\n\n3. Change ''Wombats dig and used claws'' to ''Wombats dig and use claws''.\n\n4. Yesterday a magpie visited the yard; birds have feathers.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 550 150\"><rect width=\"550\" height=\"150\" rx=\"9\" fill=\"#f2f7f3\"/><rect x=\"10\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#dcece3\"/><text x=\"17\" y=\"76\" font-family=\"Arial\" font-size=\"15\">NOTICE</text><rect x=\"146\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#e7ebf7\"/><text x=\"153\" y=\"76\" font-family=\"Arial\" font-size=\"15\">EXPLAIN</text><rect x=\"282\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#dcece3\"/><text x=\"289\" y=\"76\" font-family=\"Arial\" font-size=\"15\">APPLY</text><rect x=\"418\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#e7ebf7\"/><text x=\"425\" y=\"76\" font-family=\"Arial\" font-size=\"15\">VERIFY</text></svg>","alt":"Four phases of Timeless Present: Write Accurate General Facts","caption":"Notice, explain, apply and verify."}],"guided_practice":"Study these original examples before trying an independent response: A report states ''A wombat digs burrows. Wombats have strong claws. Their burrows provide shelter.''\n\nA wombat digs burrows; ''dug yesterday'' describes a past event. A bee visits flowers, but bees visit flowers. Change ''Wombats dig and used claws'' to ''Wombats dig and use claws''. Yesterday a magpie visited the yard; birds have feathers.\n\nExplain one choice before comparing it with this model.","independent_task":"Revise: ''Birds has feathers. A kookaburra eat insects and sometimes calls loudly. Many birds built nests to raise young. Yesterday a magpie visits our yard.'' Use timeless present for general facts, past tense for the dated observation, and explain three verb corrections.","response_prompt":"Revise: ''Birds has feathers. A kookaburra eat insects and sometimes calls loudly. Many birds built nests to raise young. Yesterday a magpie visits our yard.'' Use timeless present for general facts, past tense for the dated observation, and explain three verb corrections.","quiz":[{"type":"multiple_choice","question":"General present fact?","options":["A wombat digs burrows.","A wombat dug yesterday.","Tomorrow it will dig.","I saw it last week."],"correct_index":0,"explanation":"A wombat digs burrows.. Compare with the taught example."},{"type":"multiple_choice","question":"Correct singular form?","options":["A bee visits flowers.","A bee visit flowers.","A bee visited always.","A bee are visiting."],"correct_index":0,"explanation":"A bee visits flowers.. Compare with the taught example."},{"type":"multiple_choice","question":"Correct plural form?","options":["Bees visits flowers.","Bees visit flowers.","Bees has visits.","Bees is visit."],"correct_index":1,"explanation":"Bees visit flowers.. Compare with the taught example."},{"type":"multiple_choice","question":"Tense for yesterday?","options":["Past","Future","Timeless present only","No verb"],"correct_index":0,"explanation":"Past. Compare with the taught example."},{"type":"multiple_choice","question":"Which is consistent?","options":["Birds have feathers and build nests.","Birds has feathers.","Birds have feathers and built nests.","Birds had feathers and build nests."],"correct_index":0,"explanation":"Birds have feathers and build nests.. Compare with the taught example."},{"type":"multiple_choice","question":"Which is correct?","options":["Earthworms move through soil.","Earthworms moves soil.","Earthworms moving soil.","Earthworms is move."],"correct_index":0,"explanation":"Earthworms move through soil.. Compare with the taught example."},{"type":"multiple_choice","question":"Which needs qualification?","options":["Every bird can fly.","A magpie is a bird.","Many birds have feathers.","Some birds make nests."],"correct_index":0,"explanation":"Every bird can fly.. Compare with the taught example."},{"type":"multiple_choice","question":"When use timeless present?","options":["General information","Only yesterday''s event","Random changes","Only a prediction"],"correct_index":0,"explanation":"General information. Compare with the taught example."},{"type":"short_answer","question":"Complete the original independent challenge with supporting evidence or calculations.","sample_answer":"Birds have feathers. A kookaburra eats insects and sometimes calls loudly. Many birds build nests to raise their young. Yesterday, a magpie visited our yard.","marking_guide":"Check complete, accurate topic-specific content and reasoning.","explanation":"An answer should show its method."},{"type":"short_answer","question":"Explain a relevant correction or improvement.","sample_answer":"I changed has to have for plural birds, eat to eats for a singular kookaburra, built to build for a general fact, and visits to visited for the past event.","marking_guide":"Check complete, accurate topic-specific content and reasoning.","explanation":"An answer should show its method."}],"parent_notes":"Parent: Require the child''s original work before revealing marking models.\n\nParent: First model answer: Birds have feathers. A kookaburra eats insects and sometimes calls loudly. Many birds build nests to raise their young. Yesterday, a magpie visited our yard.\n\nParent: Second model answer: I changed has to have for plural birds, eat to eats for a singular kookaburra, built to build for a general fact, and visits to visited for the past event.\n\nParent: Keep evidence and verify NESA outcomes before approval.","evidence_instructions":"Keep the independent response, one revision and both written answers.","offline_alternative":"Complete the example and task on paper and keep the result.","extension":"Create another example of timeless present: write accurate general facts and explain it.","stage_hints":{"accept":["Read the Timeless Present: Write Accurate General Facts instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach0":["Read the Use simple present tense for general facts. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach1":["Read the Match singular and plural subjects to verbs. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach2":["Read the Keep tense consistent within a general explanation. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach3":["Read the Separate dated past events from ongoing general facts. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"learn":["Read the Timeless Present: Write Accurate General Facts instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"guided":["Read the Timeless Present: Write Accurate General Facts instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"write":["Read the Timeless Present: Write Accurate General Facts instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"quiz":["Read the Timeless Present: Write Accurate General Facts instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"submit":["Read the Timeless Present: Write Accurate General Facts instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."]}}') WHERE seed_key='s2-eng-y3-w08-l3';
UPDATE lessons SET title='Oral Presentation: Speak Clearly for an Audience',data=json_patch(data,'{"seed_key":"s2-eng-y3-w08-l4","title":"Oral Presentation: Speak Clearly for an Audience","stage":"Stage 2","learning_area":"English","year_level":3,"week":8,"lesson_number":4,"duration_minutes":60,"child_mission":"Investigate oral presentation: speak clearly for an audience with detailed modelling and independent practice.","learning_intention":"We are learning to understand and apply oral presentation: speak clearly for an audience.","success_criteria":["I can describe the key idea.","I can follow and explain a worked model.","I can practise and check feedback.","I can solve an independent challenge.","I can explain an improvement."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Teaching reminders","cards":[{"front":"Identify audience, topic and purpose.","back":"Begin ''Today I''ll explain how our garden compost system works.''"},{"front":"Organise introduction, key points and conclusion.","back":"Introduce the bin, describe suitable inputs, then explain why it helps."},{"front":"Speak audibly and pause between ideas.","back":"A labelled diagram supports ideas; tiny paragraphs on slides don''t."},{"front":"Rehearse and improve from specific listener feedback.","back":"If listeners miss a step, revise that instruction and rehearse again."}]}],"printable_resource":{"title":"Oral Presentation: Speak Clearly for an Audience","instructions":"Learn, practise, apply and check.","passage":"A child will explain a school compost bin to classmates who haven''t used it.","prompts":["What do I know?","How does the example work?","Try the independent challenge.","Explain one check."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Identify audience, topic and purpose.","explain":"Identify audience, topic and purpose. For example: Begin ''Today I''ll explain how our garden compost system works.''\n\nOriginal source: A child will explain a school compost bin to classmates who haven''t used it.","example":"**Worked thinking:** Begin ''Today I''ll explain how our garden compost system works.''\n\n**New attempt:** Prepare a 60–90-second presentation called ''Care for Our Community Garden''. Include a clear introduction, three actions, one labelled diagram, and a conclusion. Present orally or via an accessible signed or typed alternative, then write three sentences on one change you made after rehearsal.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"Begin ''Today I''ll explain how our garden compost system works.''","check":{"question":"What belongs in an opening?","options":["Clear purpose","Unrelated joke only","No topic","Tiny unreadable text"],"correct_index":0,"explanation":"Begin ''Today I''ll explain how our garden compost system works.''"},"visual_before":[{"episode":{"title":"Oral Presentation: Speak Clearly for an Audience","transcript":"pip: I''ll put every word of my talk on one slide!\njuno: Your audience needs a few clear points and a useful visual.\npip: I''ll introduce, explain three things and finish with a reminder.\njuno: Pause and practise your opening slowly and clearly.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I''ll put every word of my talk on one slide!"},{"who":"juno","text":"Your audience needs a few clear points and a useful visual."},{"who":"pip","text":"I''ll introduce, explain three things and finish with a reminder."},{"who":"juno","text":"Pause and practise your opening slowly and clearly.","pause_after":true}]}]}}]},{"icon":"📘","title":"Organise introduction, key points and conclusion.","explain":"Organise introduction, key points and conclusion. For example: Introduce the bin, describe suitable inputs, then explain why it helps.\n\nOriginal source: A child will explain a school compost bin to classmates who haven''t used it.","example":"**Worked thinking:** Introduce the bin, describe suitable inputs, then explain why it helps.\n\n**New attempt:** Prepare a 60–90-second presentation called ''Care for Our Community Garden''. Include a clear introduction, three actions, one labelled diagram, and a conclusion. Present orally or via an accessible signed or typed alternative, then write three sentences on one change you made after rehearsal.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"Introduce the bin, describe suitable inputs, then explain why it helps.","check":{"question":"Good talk order?","options":["Opening, points, conclusion","Ending first with unrelated middle","No order","Only the conclusion"],"correct_index":0,"explanation":"Introduce the bin, describe suitable inputs, then explain why it helps."}},{"icon":"✏️","title":"Speak audibly and pause between ideas.","explain":"Speak audibly and pause between ideas. For example: A labelled diagram supports ideas; tiny paragraphs on slides don''t.\n\nOriginal source: A child will explain a school compost bin to classmates who haven''t used it.","example":"**Worked thinking:** A labelled diagram supports ideas; tiny paragraphs on slides don''t.\n\n**New attempt:** Prepare a 60–90-second presentation called ''Care for Our Community Garden''. Include a clear introduction, three actions, one labelled diagram, and a conclusion. Present orally or via an accessible signed or typed alternative, then write three sentences on one change you made after rehearsal.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"A labelled diagram supports ideas; tiny paragraphs on slides don''t.","check":{"question":"Useful visual?","options":["Simple labelled diagram","Unrelated screenshot","Tiny text wall","Blank screen"],"correct_index":0,"explanation":"A labelled diagram supports ideas; tiny paragraphs on slides don''t."}},{"icon":"✅","title":"Rehearse and improve from specific listener feedback.","explain":"Rehearse and improve from specific listener feedback. For example: If listeners miss a step, revise that instruction and rehearse again.\n\nOriginal source: A child will explain a school compost bin to classmates who haven''t used it.","example":"**Worked thinking:** If listeners miss a step, revise that instruction and rehearse again.\n\n**New attempt:** Prepare a 60–90-second presentation called ''Care for Our Community Garden''. Include a clear introduction, three actions, one labelled diagram, and a conclusion. Present orally or via an accessible signed or typed alternative, then write three sentences on one change you made after rehearsal.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"If listeners miss a step, revise that instruction and rehearse again.","check":{"question":"Why pause?","options":["Help audience understand","Hide mistakes","Replace teaching","Add confusion"],"correct_index":0,"explanation":"If listeners miss a step, revise that instruction and rehearse again."}}],"worked_example":"1. Begin ''Today I''ll explain how our garden compost system works.''\n\n2. Introduce the bin, describe suitable inputs, then explain why it helps.\n\n3. A labelled diagram supports ideas; tiny paragraphs on slides don''t.\n\n4. If listeners miss a step, revise that instruction and rehearse again.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 550 150\"><rect width=\"550\" height=\"150\" rx=\"9\" fill=\"#f2f7f3\"/><rect x=\"10\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#dcece3\"/><text x=\"17\" y=\"76\" font-family=\"Arial\" font-size=\"15\">NOTICE</text><rect x=\"146\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#e7ebf7\"/><text x=\"153\" y=\"76\" font-family=\"Arial\" font-size=\"15\">EXPLAIN</text><rect x=\"282\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#dcece3\"/><text x=\"289\" y=\"76\" font-family=\"Arial\" font-size=\"15\">APPLY</text><rect x=\"418\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#e7ebf7\"/><text x=\"425\" y=\"76\" font-family=\"Arial\" font-size=\"15\">VERIFY</text></svg>","alt":"Four phases of Oral Presentation: Speak Clearly for an Audience","caption":"Notice, explain, apply and verify."}],"guided_practice":"Study these original examples before trying an independent response: A child will explain a school compost bin to classmates who haven''t used it.\n\nBegin ''Today I''ll explain how our garden compost system works.'' Introduce the bin, describe suitable inputs, then explain why it helps. A labelled diagram supports ideas; tiny paragraphs on slides don''t. If listeners miss a step, revise that instruction and rehearse again.\n\nExplain one choice before comparing it with this model.","independent_task":"Prepare a 60–90-second presentation called ''Care for Our Community Garden''. Include a clear introduction, three actions, one labelled diagram, and a conclusion. Present orally or via an accessible signed or typed alternative, then write three sentences on one change you made after rehearsal.","response_prompt":"Prepare a 60–90-second presentation called ''Care for Our Community Garden''. Include a clear introduction, three actions, one labelled diagram, and a conclusion. Present orally or via an accessible signed or typed alternative, then write three sentences on one change you made after rehearsal.","quiz":[{"type":"multiple_choice","question":"What belongs in an opening?","options":["Clear purpose","Unrelated joke only","No topic","Tiny unreadable text"],"correct_index":0,"explanation":"Clear purpose. Compare with the taught example."},{"type":"multiple_choice","question":"Good talk order?","options":["Opening, points, conclusion","Ending first with unrelated middle","No order","Only the conclusion"],"correct_index":0,"explanation":"Opening, points, conclusion. Compare with the taught example."},{"type":"multiple_choice","question":"Useful visual?","options":["Simple labelled diagram","Unrelated screenshot","Tiny text wall","Blank screen"],"correct_index":0,"explanation":"Simple labelled diagram. Compare with the taught example."},{"type":"multiple_choice","question":"Why pause?","options":["Help audience understand","Hide mistakes","Replace teaching","Add confusion"],"correct_index":0,"explanation":"Help audience understand. Compare with the taught example."},{"type":"multiple_choice","question":"How check clarity?","options":["Ask listener to explain key points","Only count words","Add more random ideas","Speak faster"],"correct_index":0,"explanation":"Ask listener to explain key points. Compare with the taught example."},{"type":"multiple_choice","question":"What makes advice accurate?","options":["Follow local garden rules","Invent universal rules","Ignore guidelines","Claim all compost is same"],"correct_index":0,"explanation":"Follow local garden rules. Compare with the taught example."},{"type":"multiple_choice","question":"Meaningful revision?","options":["Clarify unclear instruction","Change random font","Add irrelevant facts","Remove topic"],"correct_index":0,"explanation":"Clarify unclear instruction. Compare with the taught example."},{"type":"multiple_choice","question":"Accessible option?","options":["Signed or typed explanation","No alternative","Only a stage performance","Only a poster"],"correct_index":0,"explanation":"Signed or typed explanation. Compare with the taught example."},{"type":"short_answer","question":"Complete the original independent challenge with supporting evidence or calculations.","sample_answer":"My talk introduces garden care, explains following watering instructions, keeping pathways clear and treating plants gently. A labelled sketch shows the paths and beds, and the ending reminds listeners to respect shared spaces.","marking_guide":"Check complete, accurate topic-specific content and reasoning.","explanation":"An answer should show its method."},{"type":"short_answer","question":"Explain a relevant correction or improvement.","sample_answer":"I changed ''water whenever'' to ''follow the garden watering guidance'' after feedback. I paused between steps so the listener could follow.","marking_guide":"Check complete, accurate topic-specific content and reasoning.","explanation":"An answer should show its method."}],"parent_notes":"Parent: Require the child''s original work before revealing marking models.\n\nParent: First model answer: My talk introduces garden care, explains following watering instructions, keeping pathways clear and treating plants gently. A labelled sketch shows the paths and beds, and the ending reminds listeners to respect shared spaces.\n\nParent: Second model answer: I changed ''water whenever'' to ''follow the garden watering guidance'' after feedback. I paused between steps so the listener could follow.\n\nParent: Keep evidence and verify NESA outcomes before approval.","evidence_instructions":"Keep the independent response, one revision and both written answers.","offline_alternative":"Complete the example and task on paper and keep the result.","extension":"Create another example of oral presentation: speak clearly for an audience and explain it.","stage_hints":{"accept":["Read the Oral Presentation: Speak Clearly for an Audience instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach0":["Read the Identify audience, topic and purpose. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach1":["Read the Organise introduction, key points and conclusion. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach2":["Read the Speak audibly and pause between ideas. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach3":["Read the Rehearse and improve from specific listener feedback. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"learn":["Read the Oral Presentation: Speak Clearly for an Audience instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"guided":["Read the Oral Presentation: Speak Clearly for an Audience instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"write":["Read the Oral Presentation: Speak Clearly for an Audience instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"quiz":["Read the Oral Presentation: Speak Clearly for an Audience instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"submit":["Read the Oral Presentation: Speak Clearly for an Audience instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."]}}') WHERE seed_key='s2-eng-y3-w08-l4';
UPDATE lessons SET title='Estimate Sums and Differences: Check Reasonableness',data=json_patch(data,'{"seed_key":"s2-mat-y3-w08-l1","title":"Estimate Sums and Differences: Check Reasonableness","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":8,"lesson_number":1,"duration_minutes":60,"child_mission":"Investigate estimate sums and differences: check reasonableness with detailed modelling and independent practice.","learning_intention":"We are learning to understand and apply estimate sums and differences: check reasonableness.","success_criteria":["I can describe the key idea.","I can follow and explain a worked model.","I can practise and check feedback.","I can solve an independent challenge.","I can explain an improvement."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Teaching reminders","cards":[{"front":"Identify whether to add or subtract before estimating.","back":"Combine sales: 478+326; subtract 189 refunds afterwards."},{"front":"Round to a stated place-value unit.","back":"478≈500, 326≈300, so about 800 tickets were sold."},{"front":"Calculate the exact result after estimating.","back":"478+326=804; 804−189=615 after refunds."},{"front":"Compare estimates and exact results to catch errors.","back":"800−200≈600, close to 615; a result of 1,615 would be unreasonable."}]}],"printable_resource":{"title":"Estimate Sums and Differences: Check Reasonableness","instructions":"Learn, practise, apply and check.","passage":"A fundraiser sells 478 tickets before lunch and 326 afterwards, then refunds 189.","prompts":["What do I know?","How does the example work?","Try the independent challenge.","Explain one check."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Identify whether to add or subtract before estimating.","explain":"Identify whether to add or subtract before estimating. For example: Combine sales: 478+326; subtract 189 refunds afterwards.\n\nOriginal source: A fundraiser sells 478 tickets before lunch and 326 afterwards, then refunds 189.","example":"**Worked thinking:** Combine sales: 478+326; subtract 189 refunds afterwards.\n\n**New attempt:** A classroom orders 367 exercise books and 458 pencils, then gives away 279 items. Estimate sum and difference using rounding to the nearest hundred, compute exact totals and explain why 367+458 is 825 rather than 925. Use an inverse check.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"Combine sales: 478+326; subtract 189 refunds afterwards.","check":{"question":"478+326?","options":["794","804","814","904"],"correct_index":1,"explanation":"Combine sales: 478+326; subtract 189 refunds afterwards."},"visual_before":[{"episode":{"title":"Estimate Sums and Differences: Check Reasonableness","transcript":"pip: Four hundred seventy-eight plus three hundred twenty-six seems hard.\njuno: Estimate: five hundred plus three hundred is about eight hundred.\npip: The exact answer is eight hundred and four.\njuno: Now pause and estimate after refunding one hundred eighty-nine.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"Four hundred seventy-eight plus three hundred twenty-six seems hard."},{"who":"juno","text":"Estimate: five hundred plus three hundred is about eight hundred."},{"who":"pip","text":"The exact answer is eight hundred and four."},{"who":"juno","text":"Now pause and estimate after refunding one hundred eighty-nine.","pause_after":true}]}]}}]},{"icon":"📘","title":"Round to a stated place-value unit.","explain":"Round to a stated place-value unit. For example: 478≈500, 326≈300, so about 800 tickets were sold.\n\nOriginal source: A fundraiser sells 478 tickets before lunch and 326 afterwards, then refunds 189.","example":"**Worked thinking:** 478≈500, 326≈300, so about 800 tickets were sold.\n\n**New attempt:** A classroom orders 367 exercise books and 458 pencils, then gives away 279 items. Estimate sum and difference using rounding to the nearest hundred, compute exact totals and explain why 367+458 is 825 rather than 925. Use an inverse check.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"478≈500, 326≈300, so about 800 tickets were sold.","check":{"question":"478 nearest hundred?","options":["400","470","500","600"],"correct_index":2,"explanation":"478≈500, 326≈300, so about 800 tickets were sold."}},{"icon":"✏️","title":"Calculate the exact result after estimating.","explain":"Calculate the exact result after estimating. For example: 478+326=804; 804−189=615 after refunds.\n\nOriginal source: A fundraiser sells 478 tickets before lunch and 326 afterwards, then refunds 189.","example":"**Worked thinking:** 478+326=804; 804−189=615 after refunds.\n\n**New attempt:** A classroom orders 367 exercise books and 458 pencils, then gives away 279 items. Estimate sum and difference using rounding to the nearest hundred, compute exact totals and explain why 367+458 is 825 rather than 925. Use an inverse check.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"478+326=804; 804−189=615 after refunds.","check":{"question":"326 nearest hundred?","options":["300","320","400","200"],"correct_index":0,"explanation":"478+326=804; 804−189=615 after refunds."}},{"icon":"✅","title":"Compare estimates and exact results to catch errors.","explain":"Compare estimates and exact results to catch errors. For example: 800−200≈600, close to 615; a result of 1,615 would be unreasonable.\n\nOriginal source: A fundraiser sells 478 tickets before lunch and 326 afterwards, then refunds 189.","example":"**Worked thinking:** 800−200≈600, close to 615; a result of 1,615 would be unreasonable.\n\n**New attempt:** A classroom orders 367 exercise books and 458 pencils, then gives away 279 items. Estimate sum and difference using rounding to the nearest hundred, compute exact totals and explain why 367+458 is 825 rather than 925. Use an inverse check.\n\n**Check:** Explain why your decision fits this lesson''s method.","notice":"800−200≈600, close to 615; a result of 1,615 would be unreasonable.","check":{"question":"804−189?","options":["605","615","625","715"],"correct_index":1,"explanation":"800−200≈600, close to 615; a result of 1,615 would be unreasonable."}}],"worked_example":"1. Combine sales: 478+326; subtract 189 refunds afterwards.\n\n2. 478≈500, 326≈300, so about 800 tickets were sold.\n\n3. 478+326=804; 804−189=615 after refunds.\n\n4. 800−200≈600, close to 615; a result of 1,615 would be unreasonable.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 550 150\"><rect width=\"550\" height=\"150\" rx=\"9\" fill=\"#f2f7f3\"/><rect x=\"10\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#dcece3\"/><text x=\"17\" y=\"76\" font-family=\"Arial\" font-size=\"15\">NOTICE</text><rect x=\"146\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#e7ebf7\"/><text x=\"153\" y=\"76\" font-family=\"Arial\" font-size=\"15\">EXPLAIN</text><rect x=\"282\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#dcece3\"/><text x=\"289\" y=\"76\" font-family=\"Arial\" font-size=\"15\">APPLY</text><rect x=\"418\" y=\"25\" width=\"128\" height=\"99\" rx=\"8\" fill=\"#e7ebf7\"/><text x=\"425\" y=\"76\" font-family=\"Arial\" font-size=\"15\">VERIFY</text></svg>","alt":"Four phases of Estimate Sums and Differences: Check Reasonableness","caption":"Notice, explain, apply and verify."}],"guided_practice":"Study these original examples before trying an independent response: A fundraiser sells 478 tickets before lunch and 326 afterwards, then refunds 189.\n\nCombine sales: 478+326; subtract 189 refunds afterwards. 478≈500, 326≈300, so about 800 tickets were sold. 478+326=804; 804−189=615 after refunds. 800−200≈600, close to 615; a result of 1,615 would be unreasonable.\n\nExplain one choice before comparing it with this model.","independent_task":"A classroom orders 367 exercise books and 458 pencils, then gives away 279 items. Estimate sum and difference using rounding to the nearest hundred, compute exact totals and explain why 367+458 is 825 rather than 925. Use an inverse check.","response_prompt":"A classroom orders 367 exercise books and 458 pencils, then gives away 279 items. Estimate sum and difference using rounding to the nearest hundred, compute exact totals and explain why 367+458 is 825 rather than 925. Use an inverse check.","quiz":[{"type":"multiple_choice","question":"478+326?","options":["794","804","814","904"],"correct_index":1,"explanation":"804. Compare with the taught example."},{"type":"multiple_choice","question":"478 nearest hundred?","options":["400","470","500","600"],"correct_index":2,"explanation":"500. Compare with the taught example."},{"type":"multiple_choice","question":"326 nearest hundred?","options":["300","320","400","200"],"correct_index":0,"explanation":"300. Compare with the taught example."},{"type":"multiple_choice","question":"804−189?","options":["605","615","625","715"],"correct_index":1,"explanation":"615. Compare with the taught example."},{"type":"multiple_choice","question":"287+416?","options":["693","703","713","803"],"correct_index":1,"explanation":"703. Compare with the taught example."},{"type":"multiple_choice","question":"702−286?","options":["406","416","426","516"],"correct_index":1,"explanation":"416. Compare with the taught example."},{"type":"multiple_choice","question":"367+458?","options":["815","825","835","925"],"correct_index":1,"explanation":"825. Compare with the taught example."},{"type":"multiple_choice","question":"825−279?","options":["536","546","556","646"],"correct_index":1,"explanation":"546. Compare with the taught example."},{"type":"short_answer","question":"Complete the original independent challenge with supporting evidence or calculations.","sample_answer":"The estimate is about 400+500=900 items. The exact total is 367+458=825, and 825−279=546 remain; rounded estimate 800−300=500.","marking_guide":"Check complete, accurate topic-specific content and reasoning.","explanation":"An answer should show its method."},{"type":"short_answer","question":"Explain a relevant correction or improvement.","sample_answer":"367+458 is 825: 300+400=700; 60+50=110; 7+8=15; total 825. The inverse check is 825−458=367.","marking_guide":"Check complete, accurate topic-specific content and reasoning.","explanation":"An answer should show its method."}],"parent_notes":"Parent: Require the child''s original work before revealing marking models.\n\nParent: First model answer: The estimate is about 400+500=900 items. The exact total is 367+458=825, and 825−279=546 remain; rounded estimate 800−300=500.\n\nParent: Second model answer: 367+458 is 825: 300+400=700; 60+50=110; 7+8=15; total 825. The inverse check is 825−458=367.\n\nParent: Keep evidence and verify NESA outcomes before approval.","evidence_instructions":"Keep the independent response, one revision and both written answers.","offline_alternative":"Complete the example and task on paper and keep the result.","extension":"Create another example of estimate sums and differences: check reasonableness and explain it.","stage_hints":{"accept":["Read the Estimate Sums and Differences: Check Reasonableness instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach0":["Read the Identify whether to add or subtract before estimating. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach1":["Read the Round to a stated place-value unit. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach2":["Read the Calculate the exact result after estimating. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"teach3":["Read the Compare estimates and exact results to catch errors. instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"learn":["Read the Estimate Sums and Differences: Check Reasonableness instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"guided":["Read the Estimate Sums and Differences: Check Reasonableness instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"write":["Read the Estimate Sums and Differences: Check Reasonableness instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"quiz":["Read the Estimate Sums and Differences: Check Reasonableness instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."],"submit":["Read the Estimate Sums and Differences: Check Reasonableness instruction.","Use the original numbers or phrases to identify what matters.","Explain your result and check it against the model."]}}') WHERE seed_key='s2-mat-y3-w08-l1';
